+        '/h/.local/bin/fa',
+        '/h/.local/bin/fah',
+        '/opt/homebrew/bin/fa',
+        '/opt/homebrew/bin/fah',
+        '/usr/local/bin/fa',
+        '/usr/local/bin/fah',
+      ]) {
